-- MatchIQ schema. Data is loaded by the repeatable migration R__seed_data.sql
-- (generated by pipeline/src/export.py), so this file only changes when the model of the data changes.

CREATE TABLE dataset_meta (
    k VARCHAR(40) PRIMARY KEY,
    v TEXT        NOT NULL            -- JSON-encoded value
);

CREATE TABLE team (
    id           INT              PRIMARY KEY,
    name         VARCHAR(40)      NOT NULL UNIQUE,   -- spelling used by the data sources, e.g. "Man City"
    display_name VARCHAR(60)      NOT NULL,
    short_name   VARCHAR(5)       NOT NULL,
    elo          DOUBLE PRECISION NOT NULL,          -- current rating
    elo_rank     INT,                                -- 1 = strongest; NULL for clubs not in this season's league
    in_league    BOOLEAN          NOT NULL
);

-- Rating going into each match (point_no 1..n), plus the current rating as the last point.
CREATE TABLE team_elo_point (
    team_id    INT              NOT NULL REFERENCES team (id),
    point_no   INT              NOT NULL,
    match_date DATE             NOT NULL,
    elo        DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (team_id, point_no)
);

CREATE TABLE stat_def (
    stat_key    VARCHAR(40) PRIMARY KEY,
    label       VARCHAR(80) NOT NULL,
    description TEXT        NOT NULL,
    sort_order  INT         NOT NULL
);

CREATE TABLE player (
    id        INT              PRIMARY KEY,
    name      VARCHAR(60)      NOT NULL,
    full_name VARCHAR(120)     NOT NULL,
    team_id   INT              NOT NULL REFERENCES team (id),   -- club in the scouting season
    position  VARCHAR(12)      NOT NULL CHECK (position IN ('Defender', 'Midfielder', 'Forward')),
    minutes   INT              NOT NULL,
    style     VARCHAR(40)      NOT NULL,                        -- k-means playing style
    pca_x     DOUBLE PRECISION NOT NULL,                        -- 2-D style map coordinates
    pca_y     DOUBLE PRECISION NOT NULL
);
CREATE INDEX idx_player_name ON player (lower(name));

-- One row per player per stat. zscore is the standardised per-90 value used for similarity search.
CREATE TABLE player_stat (
    player_id  INT              NOT NULL REFERENCES player (id),
    stat_key   VARCHAR(40)      NOT NULL REFERENCES stat_def (stat_key),
    raw_value  DOUBLE PRECISION NOT NULL,
    per90      DOUBLE PRECISION NOT NULL,
    percentile DOUBLE PRECISION NOT NULL,                       -- 0-100, within the player's position
    zscore     DOUBLE PRECISION NOT NULL,
    PRIMARY KEY (player_id, stat_key)
);
CREATE INDEX idx_player_stat_board ON player_stat (stat_key, per90 DESC);

CREATE TABLE fixture (
    id           INT              PRIMARY KEY,
    gameweek     INT              NOT NULL,
    kickoff      TIMESTAMPTZ      NOT NULL,
    home_team_id INT              NOT NULL REFERENCES team (id),
    away_team_id INT              NOT NULL REFERENCES team (id),
    status       VARCHAR(10)      NOT NULL CHECK (status IN ('UPCOMING', 'FINISHED')),
    home_goals   INT,
    away_goals   INT,
    p_home       DOUBLE PRECISION NOT NULL,
    p_draw       DOUBLE PRECISION NOT NULL,
    p_away       DOUBLE PRECISION NOT NULL,
    predicted    CHAR(1)          NOT NULL CHECK (predicted IN ('H', 'D', 'A')),
    result       CHAR(1) CHECK (result IN ('H', 'D', 'A'))      -- NULL until the match is played
);
CREATE INDEX idx_fixture_status_kickoff ON fixture (status, kickoff);

CREATE TABLE model_metric (
    model    VARCHAR(40)      PRIMARY KEY,
    accuracy DOUBLE PRECISION NOT NULL,
    log_loss DOUBLE PRECISION NOT NULL,
    chosen   BOOLEAN          NOT NULL
);

CREATE TABLE model_season (
    season         VARCHAR(8)       PRIMARY KEY,
    matches        INT              NOT NULL,
    model_accuracy DOUBLE PRECISION NOT NULL,
    home_accuracy  DOUBLE PRECISION NOT NULL
);
